from functools import lru_cache
class Solution:
    def concatenatedDivisibility(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        lens = [len(str(x)) for x in nums]
        full = (1 << n) - 1
        @lru_cache(None)
        def f(mask, r):
            if mask == full:
                return r == 0
            for i in range(n):
                if not mask >> i & 1:
                    nr = (r * pow(10, lens[i], k) + nums[i]) % k
                    if f(mask | 1 << i, nr):
                        return True
            return False
        if not f(0, 0):
            return []
        res, mask, r = [], 0, 0
        for _ in range(n):
            for i in sorted(range(n), key=lambda j: nums[j]):
                if not mask >> i & 1:
                    nr = (r * pow(10, lens[i], k) + nums[i]) % k
                    if f(mask | 1 << i, nr):
                        res.append(nums[i]); mask |= 1 << i; r = nr
                        break
        return res

