class Solution {
public:
    vector<int> concatenatedDivisibility(vector<int>& nums, int k) {
        int n = nums.size(), full = (1 << n) - 1;
        vector<long long> p10(n);
        vector<int> ord(n);
        iota(ord.begin(), ord.end(), 0);
        sort(ord.begin(), ord.end(), [&](int a, int b){ return nums[a] < nums[b]; });
        for (int i = 0; i < n; i++) { p10[i] = 1; for (int t = 0; t < to_string(nums[i]).size(); t++) p10[i] = p10[i] * 10 % k; }
        vector<vector<char>> f(1 << n, vector<char>(k, -1));
        function<bool(int,int)> go = [&](int mask, int r) -> bool {
            if (mask == full) return r == 0;
            char &res = f[mask][r];
            if (res != -1) return res;
            res = 0;
            for (int i = 0; i < n && !res; i++)
                if (!(mask >> i & 1))
                    res = go(mask | 1 << i, (r * p10[i] + nums[i]) % k);
            return res;
        };
        if (!go(0, 0)) return {};
        vector<int> ans; int mask = 0, r = 0;
        for (int step = 0; step < n; step++)
            for (int idx : ord)
                if (!(mask >> idx & 1)) {
                    int nr = (int)((r * p10[idx] + nums[idx]) % k);
                    if (go(mask | 1 << idx, nr)) { ans.push_back(nums[idx]); mask |= 1 << idx; r = nr; break; }
                }
        return ans;
    }
};

