class Solution {
    int[] nums; long[] p10; Boolean[][] f; int n, full;
    public int[] concatenatedDivisibility(int[] nums, int k) {
        this.nums = nums; n = nums.length; full = (1 << n) - 1;
        p10 = new long[n]; Integer[] ord = new Integer[n];
        for (int i = 0; i < n; i++) { ord[i] = i; p10[i] = 1; for (int t = 0; t < String.valueOf(nums[i]).length(); t++) p10[i] = p10[i] * 10 % k; }
        Arrays.sort(ord, (a, b) -> nums[a] - nums[b]);
        f = new Boolean[1 << n][k];
        if (!go(0, 0)) return new int[0];
        int[] ans = new int[n]; int mask = 0, r = 0;
        for (int s = 0; s < n; s++)
            for (int idx : ord)
                if ((mask >> idx & 1) == 0) {
                    int nr = (int)((r * p10[idx] + nums[idx]) % k);
                    if (go(mask | 1 << idx, nr)) { ans[s] = nums[idx]; mask |= 1 << idx; r = nr; break; }
                }
        return ans;
    }
    boolean go(int mask, int r) {
        if (mask == full) return r == 0;
        if (f[mask][r] != null) return f[mask][r];
        boolean res = false;
        for (int i = 0; i < n && !res; i++)
            if ((mask >> i & 1) == 0)
                res = go(mask | 1 << i, (int)((r * p10[i] + nums[i]) % k));
        return f[mask][r] = res;
    }
}

