var concatenatedDivisibility = function(nums, k) {
    const n = nums.length, full = (1 << n) - 1;
    const p10 = nums.map(x => { let p = 1n, b = BigInt(k), v = BigInt(x); for (let t = 0; t < String(x).length; t++) p = p * 10n % b; return p; });
    const bn = nums.map(BigInt);
    const f = Array.from({length: 1 << n}, () => new Array(k));
    const go = (mask, r) => {
        if (mask === full) return r === 0n;
        if (f[mask][Number(r)] !== undefined) return f[mask][Number(r)];
        let res = false;
        for (let i = 0; i < n && !res; i++)
            if (!(mask >> i & 1))
                res = go(mask | 1 << i, (r * p10[i] + bn[i]) % BigInt(k));
        return f[mask][Number(r)] = res;
    };
    if (!go(0, 0n)) return [];
    const ord = [...Array(n).keys()].sort((a, b) => nums[a] - nums[b]);
    const ans = []; let mask = 0, r = 0n;
    for (let s = 0; s < n; s++)
        for (const i of ord)
            if (!(mask >> i & 1)) {
                const nr = (r * p10[i] + bn[i]) % BigInt(k);
                if (go(mask | 1 << i, nr)) { ans.push(nums[i]); mask |= 1 << i; r = nr; break; }
            }
    return ans;
};
